import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.E8pQZ6KS.js";const u=JSON.parse('{"title":"计算机组成与系统结构","description":"","frontmatter":{},"headers":[],"relativePath":"专业基础/计算机组成与系统结构.md","filePath":"专业基础/计算机组成与系统结构.md","lastUpdated":1792430298000}'),d={name:"专业基础/计算机组成与系统结构.md"};function i(o,t,h,n,s,_){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="计算机组成与系统结构" tabindex="-1">计算机组成与系统结构 <a class="header-anchor" href="#计算机组成与系统结构" aria-label="Permalink to &quot;计算机组成与系统结构&quot;">​</a></h1><blockquote><p>从晶体管到 CPU 再到指令集。理解「机器如何执行程序」，是二进制安全、系统安全的物理前提。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>漏洞（缓冲区溢出、ROP 等）本质是程序与硬件/操作系统交互时的边界错误；</li><li>理解寄存器、栈帧、指令执行流程，才能看懂反汇编与调试器输出；</li><li>为 <a href="./操作系统.html">操作系统</a>、<a href="./汇编语言.html">汇编语言</a>、<a href="./../安全方向/二进制安全与逆向.html">二进制安全与逆向</a> 提供基础。</li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><ul><li>数据的表示与运算（补码、浮点）</li><li>存储体系（寄存器、Cache、内存、磁盘）</li><li>指令系统与寻址方式</li><li>CPU 结构（控制器、运算器、流水线）</li><li>输入输出与总线</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>《计算机组成原理》教材（校内指定）</td><td>教材</td><td>以课程为主线</td></tr><tr><td>王道考研《计算机组成原理》</td><td>教辅/视频</td><td>考点梳理清晰</td></tr><tr><td>《深入理解计算机系统》（CSAPP）</td><td>书</td><td>从程序员视角讲计算机系统，网安必读</td></tr><tr><td>Nand2Tetris（<a href="https://www.nand2tetris.org/" target="_blank" rel="noreferrer">nand2tetris.org</a>）</td><td>在线课程</td><td>从逻辑门到计算机「手搓」一台电脑</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>重点搞清楚<strong>栈与函数调用</strong>（调用约定、栈帧布局）——这是日后看漏洞的必备视角；</li><li>CSAPP 的 3 章（汇编、栈、链接）建议大二假期精读；</li><li>学完组成原理再看汇编，很多「为什么」会豁然开朗。</li></ul>',10)])])}const b=a(d,[["render",i]]);export{u as __pageData,b as default};
